#include <assert.h>
#include <stdio.h>

#include "app/velacare/velacare_state.h"

static void set_all_online(struct velacare_state_s *ctx)
{
    ctx->gateway_online = true;
    ctx->wifi_online = true;
    ctx->smoke_online = true;
    ctx->water_online = true;
    ctx->door_online = true;
    ctx->fall_online = true;
}

int main(void)
{
    struct velacare_state_s ctx;

    velacare_state_init(&ctx);
    assert(ctx.current == VELACARE_STATE_NORMAL);

    ctx.gateway_online = false;
    assert(velacare_state_evaluate(&ctx, 100));
    assert(ctx.current == VELACARE_STATE_OFFLINE);

    set_all_online(&ctx);
    ctx.smoke_alarm = true;
    assert(velacare_state_evaluate(&ctx, 200));
    assert(ctx.current == VELACARE_STATE_WARNING);
    assert(velacare_state_evaluate(&ctx, 5200));
    assert(ctx.current == VELACARE_STATE_EMERGENCY);

    ctx.smoke_alarm = false;
    assert(velacare_state_evaluate(&ctx, 5300));
    assert(ctx.current == VELACARE_STATE_NORMAL);

    ctx.smoke_alarm = true;
    assert(velacare_state_evaluate(&ctx, 5400));
    assert(ctx.current == VELACARE_STATE_WARNING);
    ctx.gateway_online = false;
    ctx.smoke_alarm = false;
    assert(velacare_state_evaluate(&ctx, 5500));
    assert(ctx.current == VELACARE_STATE_OFFLINE);

    set_all_online(&ctx);
    assert(velacare_state_evaluate(&ctx, 5600));
    assert(ctx.current == VELACARE_STATE_NORMAL);

    ctx.water_online = false;
