#include <Arduino.h>

namespace {

constexpr uint32_t kBaudRate = 115200;
constexpr int kGatewayRxPin = 18;
constexpr int kGatewayTxPin = 17;
constexpr uint32_t kHeartbeatMs = 1000;

enum SensorState : uint8_t {
  kOffline = 0,
  kNormal = 1,
  kAlarm = 2,
};

HardwareSerial d12xSerial(1);
SensorState sensorStates[4] = {kNormal, kNormal, kNormal, kNormal};
bool wifiOnline = false;
uint32_t sequenceNumber = 1;
uint32_t lastHeartbeatMs = 0;
char commandBuffer[64] = {};
size_t commandLength = 0;

uint16_t crc16CcittFalse(const uint8_t *data, size_t length) {
  uint16_t crc = 0xFFFF;
  for (size_t i = 0; i < length; ++i) {
    crc ^= static_cast<uint16_t>(data[i]) << 8;
    for (uint8_t bit = 0; bit < 8; ++bit) {
      crc = (crc & 0x8000) ? static_cast<uint16_t>((crc << 1) ^ 0x1021)
                           : static_cast<uint16_t>(crc << 1);
    }
  }
  return crc;
}

const char *stateName(SensorState state) {
  switch (state) {
    case kOffline:
      return "offline";
    case kNormal:
      return "normal";
    case kAlarm:
      return "alarm";
  }
  return "invalid";
}

void printStatus() {
  Serial.printf("STATUS smoke=%s water=%s door=%s fall=%s wifi=%s\n",
                stateName(sensorStates[0]), stateName(sensorStates[1]),
                stateName(sensorStates[2]), stateName(sensorStates[3]),
                wifiOnline ? "online" : "offline");
}

bool parseState(const char *text, SensorState &state) {
  if (strcmp(text, "offline") == 0) {
    state = kOffline;
  } else if (strcmp(text, "normal") == 0) {
    state = kNormal;
  } else if (strcmp(text, "alarm") == 0) {
    state = kAlarm;
  } else {
    return false;
  }
  return true;
}

void handleCommand(char *line) {
  while (*line == ' ') {
    ++line;
  }

  if (strcmp(line, "status") == 0) {
    printStatus();
    return;
  }
  if (strcmp(line, "normal") == 0) {
    for (SensorState &state : sensorStates) {
      state = kNormal;
    }
    Serial.println("OK all sensors normal");
    return;
  }

  char *separator = strchr(line, ' ');
  if (separator == nullptr) {
    Serial.println("ERR use: status | normal | <smoke|water|door|fall> <offline|normal|alarm> | wifi <offline|online>");
    return;
  }
  *separator = '\0';
  const char *value = separator + 1;
  while (*value == ' ') {
    ++value;
  }

  if (strcmp(line, "wifi") == 0) {
    if (strcmp(value, "online") == 0) {
      wifiOnline = true;
    } else if (strcmp(value, "offline") == 0) {
      wifiOnline = false;
    } else {
      Serial.println("ERR wifi must be offline or online");
      return;
    }
    printStatus();
    return;
  }

  int sensorIndex = -1;
  if (strcmp(line, "smoke") == 0) sensorIndex = 0;
  if (strcmp(line, "water") == 0) sensorIndex = 1;
  if (strcmp(line, "door") == 0) sensorIndex = 2;
  if (strcmp(line, "fall") == 0) sensorIndex = 3;
  SensorState newState = kOffline;
  if (sensorIndex < 0 || !parseState(value, newState)) {
    Serial.println("ERR use: <smoke|water|door|fall> <offline|normal|alarm>");
    return;
  }
  sensorStates[sensorIndex] = newState;
  printStatus();
}

void readDebugCommands() {
  while (Serial.available() > 0) {
    const char incoming = static_cast<char>(Serial.read());
    if (incoming == '\r') {
      continue;
    }
    if (incoming == '\n') {
      commandBuffer[commandLength] = '\0';
      if (commandLength > 0) {
        handleCommand(commandBuffer);
      }
      commandLength = 0;
      continue;
    }
    if (commandLength + 1 < sizeof(commandBuffer)) {
      commandBuffer[commandLength++] = incoming;
    } else {
      commandLength = 0;
      Serial.println("ERR command too long");
    }
  }
}

void sendHeartbeat() {
  char payload[80] = {};
  const int payloadLength = snprintf(
      payload, sizeof(payload), "VC1,%lu,%u,%u,%u,%u,%u",
      static_cast<unsigned long>(sequenceNumber), sensorStates[0],
      sensorStates[1], sensorStates[2], sensorStates[3], wifiOnline ? 1 : 0);
  if (payloadLength <= 0 || static_cast<size_t>(payloadLength) >= sizeof(payload)) {
    Serial.println("ERR payload overflow");
    return;
  }

  const uint16_t crc = crc16CcittFalse(
      reinterpret_cast<const uint8_t *>(payload),
      static_cast<size_t>(payloadLength));
  char frame[96] = {};
  snprintf(frame, sizeof(frame), "%s*%04X\n", payload, crc);

  d12xSerial.print(frame);
  Serial.print("TX ");
  Serial.print(frame);
  ++sequenceNumber;
}

}  // namespace

void setup() {
  Serial.begin(kBaudRate);
  d12xSerial.begin(kBaudRate, SERIAL_8N1, kGatewayRxPin, kGatewayTxPin);
  delay(300);
  Serial.println();
  Serial.println("VelaCare ESP32-S3 gateway v0.1");
  Serial.printf("D12x UART: TX=GPIO%d RX=GPIO%d baud=%lu\n", kGatewayTxPin,
                kGatewayRxPin, static_cast<unsigned long>(kBaudRate));
  printStatus();
  sendHeartbeat();
  lastHeartbeatMs = millis();
}

void loop() {
  readDebugCommands();
  const uint32_t now = millis();
  if (static_cast<uint32_t>(now - lastHeartbeatMs) >= kHeartbeatMs) {
    lastHeartbeatMs += kHeartbeatMs;
    sendHeartbeat();
  }
  delay(2);
}
# VelaCare ESP32-S3 传感器网关

首版网关固件用于验证 ESP32-S3 与 D12x VelaCare 之间的真实 UART 数据链。

## 当前行为

- 每秒发送一帧 `VC1` 心跳，波特率 115200、8N1。
- 默认烟雾、漏水、门磁、跌倒均为正常，Wi-Fi 为离线。
- D12x 通信 UART：ESP32-S3 `TX=GPIO17`、`RX=GPIO18`。
- USB-UART 调试口会输出完全相同的发送帧。
- 每帧使用 CRC16/CCITT-FALSE，初值 `0xFFFF`、多项式 `0x1021`。

示例：

```text
VC1,1,1,1,1,1,0*XXXX
```

## 调试命令

通过 USB-UART 串口以 115200 波特率发送：

```text
status
normal
smoke alarm
smoke normal
water alarm
door alarm
fall alarm
wifi online
wifi offline
```

状态值为 `offline=0`、`normal=1`、`alarm=2`。

## 接线边界

烧录和 USB 串口验收阶段不要连接 D12x 或传感器。

后续接线时只连接：

- ESP32-S3 `GPIO17/TX` → D12x `RX1`
- ESP32-S3 `GPIO18/RX` ← D12x `TX1`（首轮只发送时可暂不接）
- ESP32-S3 `GND` ↔ D12x `GND`

两块板分别使用各自 USB 供电，不连接两块板的 3V3 或 5V。双方 UART 都是 3.3 V，不使用 5 V 电平。

